"use client";

import { useEffect, useRef, useState } from "react";
import { Inter } from "next/font/google";

const inter = Inter({ subsets: ["latin"] });

export default function DigitalCard() {
  const [isFlipped, setIsFlipped] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    audio.volume = 0.5;
    audio
      .play()
      .then(() => setIsPlaying(true))
      .catch(() => {});
  }, []);

  const startMusic = async () => {
    const audio = audioRef.current;
    if (!audio) return;

    try {
      await audio.play();
      setIsPlaying(true);
    } catch {}
  };

  const flipCard = async () => {
    await startMusic();
    setIsFlipped((prev) => !prev);
  };

  const toggleMusic = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();

    const audio = audioRef.current;
    if (!audio) return;

    if (audio.paused) {
      await audio.play();
      setIsPlaying(true);
    } else {
      audio.pause();
      setIsPlaying(false);
    }
  };

  return (
    <main
      className={`${inter.className} min-h-screen bg-[#f5f2ed] flex flex-col items-center justify-center px-5 py-12`}
    >
      <audio ref={audioRef} src='/music/card-music.mp3' loop preload='auto' />

      <button
        onClick={toggleMusic}
        aria-label={isPlaying ? "Pause music" : "Play music"}
        className='fixed right-5 top-5 z-50 flex h-10 w-10 items-center justify-center rounded-full bg-white/80 text-black shadow-md backdrop-blur transition hover:scale-105 active:scale-95'
      >
        {isPlaying ? "♫" : "♪"}
      </button>

      <div className='mb-8 text-center'>
        <p className='text-xs uppercase tracking-[0.2em] text-black/50'>
          A little something for you
        </p>
        <h1 className='mt-3 text-3xl font-medium tracking-tight text-black md:text-4xl'>
          Tap the card
        </h1>
        <p className='mt-2 text-sm text-black/60'>
          There&apos;s a message waiting on the other side.
        </p>
      </div>

      <div
        onClick={flipCard}
        className='w-full max-w-[420px] aspect-[3/4] cursor-pointer [perspective:1200px]'
        role='button'
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") flipCard();
        }}
        aria-label='Flip digital card'
      >
        <div
          className={`relative h-full w-full transition-transform duration-700 ease-[cubic-bezier(0.2,0.7,0.2,1)] ${
            isFlipped ? "[transform:rotateY(180deg)]" : ""
          }`}
          style={{ transformStyle: "preserve-3d" }}
        >
          <div className='absolute inset-0 h-full w-full overflow-hidden rounded-2xl bg-neutral-200 shadow-xl [backface-visibility:hidden]'>
            <img
              src='/images/card-front.jpg'
              alt='Card artwork'
              className='absolute inset-0 h-full w-full object-cover'
            />
          </div>

          <div className='absolute inset-0 flex h-full w-full items-center justify-center overflow-hidden rounded-2xl bg-[#fffaf3] p-8 shadow-xl [transform:rotateY(180deg)] [backface-visibility:hidden] md:p-12'>
            <div className='max-w-sm text-center'>
              <p className='text-xs uppercase tracking-[0.2em] text-black/40'>
                HAPPY BIRTHDAY PRINCES SHARON
              </p>

              <h2 className='mt-6 text-sm font-medium leading-tight tracking-tight text-black md:text-md'>
                My beautiful princess. Our very own Saraswati!! You're so
                special to the people around you; and extremely special to me
                too. I'm genuinely grateful for every laugh, conversation and
                little moment we've shared. You're truly a blessing in ways
                word's can't describe. I hope this birthday brings you as much
                happiness as you bring to everyone else. May your day be filled
                with love, laughter, and all the things that make you smile.
              </h2>

              <p className='mt-6 text-base leading-7 text-black/60'>
                P.S I might have been keeping a little secret. You’ll find out
                soon enough.
              </p>

              <p className='mt-8 text-base text-black/60'>
                With love,
                <br />
                Miles
              </p>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
